-- cpd-migration: additive
-- A PR's own title (contract §2.2 PR, §4.4, §4.5 `pr-title`; hs-d285): nullable,
-- because a PR that existed before this migration has none, and `pr open`
-- refuses it (`pr_title_required`) until `pr edit --title` sets one. One line and
-- no control characters are checked at the boundary (`PrTitle`). `prs_locked`
-- and its column list are unchanged: the title is not a Locked field. The
-- history triggers of `prs` are regenerated by the runner's reconcile.
ALTER TABLE prs ADD COLUMN title TEXT CHECK (title IS NULL OR length(title) BETWEEN 1 AND 72);
